use action_classifier::load;

const ACME: &str = r#"
format_version = 1
name = "Acme Payments"
description = "Acme payments API"
host = "acme.com"

[[rules]]
method = "GET"
subdomain = "api"
path = "/v1/payment_intents"
action_class = "payment.read"

[[rules]]
subdomain = "api"
path = "/v1/refunds/*"
action_class = "payment.refund"

[[rules]]
path = "/pricing"
action_class = "payment.read"
"#;

#[tokio::test]
async fn exact_rule_matches() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v1/payment_intents")
            .await,
        Some("payment.read")
    );
}

#[tokio::test]
async fn method_less_rule_matches_any_method() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("DELETE", "api.acme.com", "/v1/refunds/re_1")
            .await,
        Some("payment.refund")
    );
}

#[tokio::test]
async fn rule_without_subdomain_applies_to_the_host_itself() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("GET", "acme.com", "/pricing").await,
        Some("payment.read")
    );
}

#[tokio::test]
async fn unmatched_request_is_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v2/anything").await,
        None
    );
}
//! Requests that spell the same operation differently must not reach a
//! broader, less sensitive rule than the canonical spelling does.

use action_classifier::load;

const ACME: &str = r#"
format_version = 1
name = "Acme Payments"
description = "Acme payments API"
host = "acme.com"

[[rules]]
subdomain = "api"
path = "/v1/*"
action_class = "payment.read"

[[rules]]
subdomain = "api"
path = "/v1/refunds/*"
action_class = "payment.refund"

[[rules]]
subdomain = "api"
method = "DELETE"
path = "/v1/charges/*"
action_class = "payment.refund"

[[rules]]
subdomain = "api"
path = "/v1/payouts"
action_class = "payment.create"
"#;

#[tokio::test]
async fn percent_encoded_unreserved_characters_match_their_decoded_form() {
    let c = load(&[ACME]).await.unwrap();
    for path in [
        "/v1/%72efunds/x",
        "/v1/%72%65%66%75%6E%64%73/x",
        "/v1/refunds/%78",
    ] {
        assert_eq!(
            c.classify("POST", "api.acme.com", path).await,
            Some("payment.refund"),
            "{path}"
        );
    }
}

#[tokio::test]
async fn method_matching_is_case_sensitive() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("DELETE", "api.acme.com", "/v1/charges/ch_1")
            .await,
        Some("payment.refund")
    );
    for method in ["delete", "Delete"] {
        assert_eq!(
            c.classify(method, "api.acme.com", "/v1/charges/ch_1").await,
            Some("payment.read"),
            "{method}"
        );
    }
}

#[tokio::test]
async fn duplicate_path_segments_are_preserved_for_matching() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1//refunds/x").await,
        Some("payment.read")
    );
    assert_eq!(
        c.classify("POST", "api.acme.com", "//v1/refunds/x").await,
        None
    );
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/refunds//x").await,
        Some("payment.refund")
    );
}

#[tokio::test]
async fn trailing_slash_that_changes_the_class_is_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/payouts").await,
        Some("payment.create")
    );
    // `/v1/payouts/` alone would match `/v1/*` (payment.read).
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/payouts/").await,
        None
    );
    // No disagreement: both spellings are payment.read.
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v1/balance/").await,
        Some("payment.read")
    );
}

#[tokio::test]
async fn dot_segments_resolve_before_matching() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/balance/../refunds/x")
            .await,
        Some("payment.refund")
    );
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/balance/%2e%2e/refunds/x")
            .await,
        Some("payment.refund")
    );
}

#[tokio::test]
async fn ambiguous_or_malformed_paths_are_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    for path in [
        "/v1/refunds%2fx",
        "/v1\\refunds\\x",
        "/v1/refunds/%zz",
        "/v1/re funds/x",
    ] {
        assert_eq!(
            c.classify("POST", "api.acme.com", path).await,
            None,
            "{path:?}"
        );
    }
}

#[tokio::test]
async fn empty_rules_list_is_rejected() {
    let empty = r#"
format_version = 1
name = "Empty"
description = "No rules"
host = "acme.com"
rules = []
"#;
    assert!(load(&[empty]).await.is_err());
}
//! Load-time conflict detection and set-order independence.

use action_classifier::{LoadError, RuleLocation, SetError, load};

fn set(name: &str, host: &str, rules: &str) -> String {
    format!("format_version = 1\nname = {name:?}\ndescription = \"test\"\nhost = {host:?}\n{rules}")
}

fn rule(subdomain: Option<&str>, method: Option<&str>, path: Option<&str>, class: &str) -> String {
    let mut out = String::from("\n[[rules]]\n");
    for (key, value) in [("subdomain", subdomain), ("method", method), ("path", path)] {
        if let Some(value) = value {
            out.push_str(&format!("{key} = {value:?}\n"));
        }
    }
    out.push_str(&format!("action_class = {class:?}\n"));
    out
}

fn location(set: usize, name: &str, rule: usize) -> RuleLocation {
    RuleLocation {
        set,
        name: name.into(),
        rule,
    }
}

#[tokio::test]
async fn identical_rules_with_different_classes_conflict_across_sets() {
    let a = set(
        "A",
        "acme.com",
        &rule(
            Some("api"),
            Some("POST"),
            Some("/v1/refunds/*"),
            "payment.refund",
        ),
    );
    let b = set(
        "B",
        "acme.com",
        &format!(
            "{}{}",
            rule(None, None, Some("/pricing"), "payment.read"),
            rule(
                Some("api"),
                Some("POST"),
                Some("/v1/refunds/*"),
                "payment.read"
            ),
        ),
    );
    match load(&[&a, &b]).await {
        Err(LoadError::ConflictingRules { first, second }) => {
            assert_eq!(first, location(0, "A", 0));
            assert_eq!(second, location(1, "B", 1));
        }
        other => panic!("expected conflict, got {:?}", other.err()),
    }
}

#[tokio::test]
async fn conflict_message_names_both_rules() {
    let a = set("A", "acme.com", &rule(None, None, Some("/x"), "repo.read"));
    let b = set("B", "acme.com", &rule(None, None, Some("/x"), "repo.write"));
    let message = load(&[&a, &b]).await.err().unwrap().to_string();
    assert!(message.contains(r#"mapping set 0 "A" rule 0"#), "{message}");
    assert!(message.contains(r#"mapping set 1 "B" rule 0"#), "{message}");
}

#[tokio::test]
async fn conflicts_are_detected_within_one_set() {
    let a = set(
        "A",
        "acme.com",
        &format!(
            "{}{}",
            rule(None, None, Some("/x"), "repo.read"),
            rule(None, None, Some("/x"), "repo.write"),
        ),
    );
    assert!(matches!(
        load(&[&a]).await,
        Err(LoadError::ConflictingRules { .. })
    ));
}

#[tokio::test]
async fn overlapping_wildcards_with_equal_specificity_conflict() {
    // `/v1/xy` matches both patterns, and both have the same literal count,
    // wildcard count and literal prefix.
    let a = set(
        "A",
        "acme.com",
        &rule(None, None, Some("/v1/*x*"), "repo.read"),
    );
    let b = set(
        "B",
        "acme.com",
        &rule(None, None, Some("/v1/*y*"), "repo.write"),
    );
    assert!(matches!(
        load(&[&a, &b]).await,
        Err(LoadError::ConflictingRules { .. })
    ));
}

#[tokio::test]
async fn same_class_duplicates_are_harmless() {
    let a = set("A", "acme.com", &rule(None, None, Some("/x"), "repo.read"));
    let c = load(&[&a, &a]).await.unwrap();
    assert_eq!(c.classify("GET", "acme.com", "/x").await, Some("repo.read"));
}

#[tokio::test]
async fn overlaps_with_different_specificity_are_allowed() {
    let a = set("A", "acme.com", &rule(Some("*"), None, None, "repo.read"));
    let b = set(
        "B",
        "acme.com",
        &rule(Some("api"), Some("PUT"), Some("/repos/*"), "repo.write"),
    );
    let c = load(&[&a, &b]).await.unwrap();
    assert_eq!(
        c.classify("PUT", "api.acme.com", "/repos/x").await,
        Some("repo.write")
    );
    assert_eq!(
        c.classify("PUT", "www.acme.com", "/repos/x").await,
        Some("repo.read")
    );
}

#[tokio::test]
async fn rules_for_different_hosts_never_conflict() {
    let a = set("A", "acme.com", &rule(None, None, Some("/x"), "repo.read"));
    let b = set(
        "B",
        "other.com",
        &rule(None, None, Some("/x"), "repo.write"),
    );
    let c = rule(Some("api"), None, Some("/x"), "repo.write");
    let c = set("C", "acme.com", &c);
    assert!(load(&[&a, &b, &c]).await.is_ok());
}

#[tokio::test]
async fn exact_subdomain_and_bare_rule_on_the_same_host_conflict() {
    // Exact subdomains are one DNS label. These rules still name the same
    // origin and must be checked against each other.
    let a = set(
        "A",
        "eu.acme.com",
        &rule(Some("api"), None, None, "repo.read"),
    );
    let b = set(
        "B",
        "api.eu.acme.com",
        &rule(None, None, None, "repo.write"),
    );
    assert!(matches!(
        load(&[&a, &b]).await,
        Err(LoadError::ConflictingRules { .. })
    ));
}

#[tokio::test]
async fn set_order_does_not_change_classification() {
    let payments = set(
        "Payments",
        "acme.com",
        &format!(
            "{}{}{}",
            rule(Some("api"), None, Some("/v1/*"), "payment.read"),
            rule(Some("api"), None, Some("/v1/refunds/*"), "payment.refund"),
            rule(
                Some("api"),
                Some("POST"),
                Some("/v1/charges"),
                "payment.create"
            ),
        ),
    );
    let repos = set(
        "Repos",
        "acme.com",
        &format!(
            "{}{}",
            rule(Some("*"), None, None, "repo.read"),
            rule(Some("git"), Some("POST"), Some("/*"), "repo.write"),
        ),
    );
    let forward = load(&[&payments, &repos]).await.unwrap();
    let reverse = load(&[&repos, &payments]).await.unwrap();
    for (method, host, path) in [
        ("GET", "api.acme.com", "/v1/charges"),
        ("POST", "api.acme.com", "/v1/charges"),
        ("POST", "api.acme.com", "/v1/refunds/r1"),
        ("POST", "git.acme.com", "/org/repo"),
        ("GET", "git.acme.com", "/org/repo"),
        ("GET", "x.y.acme.com", "/"),
        ("GET", "acme.com", "/"),
    ] {
        assert_eq!(
            forward.classify(method, host, path).await,
            reverse.classify(method, host, path).await,
            "{method} {host}{path}"
        );
    }
}

#[tokio::test]
async fn invalid_set_errors_identify_set_name_and_rule() {
    let good = set("Good", "acme.com", &rule(None, None, None, "repo.read"));
    let bad = set(
        "Bad",
        "acme.com",
        &format!(
            "{}{}",
            rule(None, None, None, "repo.read"),
            rule(None, None, None, "payment.delete"),
        ),
    );
    match load(&[&good, &bad]).await {
        Err(LoadError::InvalidSet {
            set: 1,
            name: Some(name),
            error: SetError::UnknownActionClass { rule: 1, .. },
        }) => assert_eq!(name, "Bad"),
        other => panic!("unexpected {:?}", other.err()),
    }

    let unparsable = "format_version = 1\nnme = \"typo\"";
    match load(&[&good, unparsable]).await {
